<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ApiError, type Order, type OrderInput, type FreightQuote } from './api'
import RoutesView from './RoutesView.vue'
import MapPicker from './MapPicker.vue'
import { createSession } from './session'
const integrated = import.meta.env.MODE === 'integration'
const session = createSession(); const { state, api } = session
const email = ref(''); const password = ref(''); const busy = ref(false); const error = ref(''); const notice = ref(''); const view = ref<'list'|'form'|'detail'>('list'); const orders = ref<Order[]>([]); const selected = ref<Order | null>(null); const page = ref(0); const total = ref(0); const reason = ref(''); const editing = ref(false)
let contextVersion = 0; let operationVersion = 0
const area = ref<'orders'|'routes'>('orders'); const quote = ref<FreightQuote | null>(null); const latitude = ref(''); const longitude = ref('')
watch([() => state.actor, area], () => { contextVersion++; operationVersion++; busy.value = false }, { flush: 'sync' })
watch(() => state.actor, () => { orders.value = []; selected.value = null; quote.value = null; view.value = 'list'; area.value = 'orders'; page.value = 0; total.value = 0; reason.value = ''; latitude.value = ''; longitude.value = ''; editing.value = false; delete form.recipientEmail; Object.assign(form, blank()) }, { flush: 'sync' })
const allowed = computed(() => state.actor && ['ADMIN','OPERATOR','STORE'].includes(state.actor.role))
const blank = (): OrderInput => ({ storeId: state.actor?.role === 'STORE' ? state.actor.storeId || '' : '', originId: '', destination: { line1:'', line2:null, city:'', state:'', country:'BR' }, recipientName:'', items:[{description:'', quantity:1, unitWeightKg:''}] })
const form = reactive<OrderInput>(blank())
function message(e: unknown) { if (e instanceof ApiError) { if (e.problem.status === 401 && state.token) session.logout(); const fields = (e.problem.details || []).map(d => `${d.field}: ${d.reason}`).join('; '); return [e.problem.detail || e.problem.title, fields, e.problem.traceId ? `Referência: ${e.problem.traceId}` : ''].filter(Boolean).join(' · ') } return e instanceof Error ? e.message : 'Não foi possível concluir a operação.' }
async function run(fn: () => Promise<void>) { const actor = state.actor, token = state.token, version = contextVersion, operation = ++operationVersion; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e) { if (operation === operationVersion && version === contextVersion && (!actor || (state.actor === actor && state.token === token))) error.value = message(e) } finally { if (operation === operationVersion) busy.value = false } }
function activeRequest() { const actor = state.actor, token = state.token, version = contextVersion; return () => !!actor && state.actor === actor && state.token === token && version === contextVersion }
async function load() { await run(async () => { const active = activeRequest(); const result = await api.list(page.value); if (!active()) return; orders.value = result.items; total.value = result.totalItems; view.value = 'list' }) }
watch(area, (current, previous) => {
  if (current === 'orders' && previous === 'routes' && allowed.value) void load()
})
async function login() { await run(async () => { if (!await session.login(email.value, password.value)) return; password.value = ''; if (allowed.value) await load() }) }
function newOrder() { quote.value = null; latitude.value = ''; longitude.value = '';  delete form.recipientEmail; Object.assign(form, blank()); editing.value = false; error.value = ''; view.value = 'form' }
function editOrder() { if (!selected.value || selected.value.status !== 'DRAFT') return; const o = selected.value; latitude.value = o.destination.latitude?.toString() ?? ''; longitude.value = o.destination.longitude?.toString() ?? ''; Object.assign(form, { storeId: o.storeId, originId: o.originId, destination: { ...o.destination }, recipientName: o.recipientName, recipientEmail: o.recipientEmail, items: o.items.map(i => ({ ...i })) }); editing.value = true; error.value = ''; view.value = 'form' }
function payload(): OrderInput { const destination = { ...form.destination }; for (const [key, value, limit] of [['latitude', latitude.value, 90], ['longitude', longitude.value, 180]] as const) { if (value === '') { delete destination[key]; continue } if (!/^-?(?:\d+(?:\.\d+)?|\.\d+)$/.test(value) || Math.abs(Number(value)) > limit) throw new Error(`${key === 'latitude' ? 'Latitude' : 'Longitude'} inválida.`); destination[key] = Number(value) };  if (!destination.postalCode) delete destination.postalCode; if (destination.latitude === undefined || destination.latitude === null) delete destination.latitude; if (destination.longitude === undefined || destination.longitude === null) delete destination.longitude; return { storeId: state.actor?.role === 'STORE' ? state.actor.storeId || '' : form.storeId.trim(), originId: form.originId.trim(), destination, recipientName: form.recipientName, ...(form.recipientEmail?.trim() ? { recipientEmail: form.recipientEmail.trim() } : {}), items: form.items.map(i => ({ description: i.description, quantity: Number(i.quantity), unitWeightKg: i.unitWeightKg })) } }
async function save() { await run(async () => { const active = activeRequest(); const result = editing.value && selected.value ? await api.update(selected.value.orderId, payload()) : await api.create(payload()); if (!active()) return; selected.value = result; quote.value = null; view.value = 'detail'; notice.value = editing.value ? 'Rascunho atualizado.' : 'Pedido criado.' }) }
async function open(id: string) { await run(async () => { const active = activeRequest(); const result = await api.get(id); if (!active()) return; selected.value = result; quote.value = null; reason.value = ''; view.value = 'detail' }) }
async function confirmOrder() { if (!selected.value) return; await run(async () => { const active = activeRequest(); const result = await api.confirm(selected.value!.orderId); if (!active()) return; selected.value = result; notice.value = 'Pedido confirmado.' }) }
async function quoteOrder() {
  if (!selected.value) return
  const orderId = selected.value.orderId
  await run(async () => {
    const active = activeRequest()
    const received = await api.quote(orderId)
    if (!active()) return
    if (!selected.value || selected.value.orderId !== orderId) return
    if (received.orderId !== orderId) throw new Error('A cotação recebida não corresponde ao pedido selecionado.')
    quote.value = received
    selected.value = { ...selected.value, freightAmount: received.amount }
    notice.value = 'Cotação consultada.'
  })
}
async function cancelOrder() { if (!selected.value || !reason.value.trim()) return; await run(async () => { const active = activeRequest(); const result = await api.cancel(selected.value!.orderId, reason.value.trim()); if (!active()) return; selected.value = result; reason.value = ''; notice.value = 'Pedido cancelado.' }) }
function changePage(n: number) { page.value = n; void load() }
onMounted(async () => { await run(async () => { if (await session.restore() && allowed.value) await load() }) })
</script>
<template>
  <div class="shell"><header class="top"><a v-if="integrated" class="link" href="/">Módulos</a><div class="brand"><span class="mark">↗</span><div><strong>Fluxo</strong><small>GESTÃO LOGÍSTICA</small></div></div><div v-if="state.actor" class="identity"><span>{{ state.actor.role }}</span><button class="link" @click="session.logout(); view='list'">Sair</button></div></header>
  <main><div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="notice" class="alert success" role="status">{{ notice }}</div><p v-if="busy" role="status" class="loading">Carregando…</p>
  <section v-if="!state.actor" class="login card"><div class="eyebrow">BEM-VINDO AO FLUXO</div><h1>Seu trabalho, em movimento.</h1><p>Acesse sua conta para acompanhar e gerenciar seus pedidos.</p><form @submit.prevent="login"><label>E-mail<input v-model="email" type="email" autocomplete="username" maxlength="254" required placeholder="voce@empresa.com"></label><label>Senha<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary full" :disabled="busy">Entrar <span>→</span></button></form></section>
  <nav v-if="state.actor" aria-label="Navegação principal"><button v-if="allowed" class="link" @click="area='orders'">Pedidos</button><button v-if="state.actor.role !== 'STORE'" class="link" @click="area='routes'">Rotas</button></nav>
  <RoutesView v-if="state.actor && area === 'routes' && state.actor.role !== 'STORE'" :api="api" :role="state.actor.role" @expired="session.logout()" />
  <section v-else-if="state.actor && !allowed" class="card"><h1>Acesso a pedidos indisponível</h1><p>Seu perfil não tem acesso a esta área.</p></section>
  <template v-else-if="state.actor && allowed"><div class="page-head"><div><div class="eyebrow">OPERAÇÃO / PEDIDOS</div><h1>{{ view === 'list' ? 'Pedidos' : view === 'form' ? (editing ? 'Editar rascunho' : 'Novo pedido') : 'Detalhes do pedido' }}</h1><p>{{ view === 'list' ? 'Acompanhe os pedidos e organize suas entregas.' : 'Informações para preparar a entrega.' }}</p></div><button v-if="view === 'list'" class="primary" :disabled="busy" @click="newOrder">＋ Novo pedido</button><button v-else class="secondary" :disabled="busy" @click="load">← Voltar aos pedidos</button></div>
  <section v-if="view === 'list'" class="card list"><div class="card-head"><div><h2>Todos os pedidos</h2><p>{{ total }} resultado(s)</p></div></div><div v-if="!busy && !orders.length" class="empty"><div class="empty-icon">◇</div><h3>Nenhum pedido por aqui</h3><p>Crie um pedido para começar a acompanhar sua operação.</p></div><div v-else class="table-wrap"><table><thead><tr><th>Pedido</th><th>Destinatário</th><th>Destino</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="o in orders" :key="o.orderId"><td class="mono">{{ o.orderId }}</td><td>{{ o.recipientName }}</td><td>{{ o.destination.city }} / {{ o.destination.state }}</td><td><span class="badge" :class="o.status">{{ {DRAFT:'Rascunho',CONFIRMED:'Confirmado',CANCELLED:'Cancelado'}[o.status] }}</span></td><td><button class="link" :disabled="busy" @click="open(o.orderId)">Ver detalhes <span class="sr-only">de {{ o.recipientName }}</span>→</button></td></tr></tbody></table></div><div class="pagination"><button class="secondary" :disabled="page === 0 || busy" @click="changePage(page-1)">Anterior</button><span>Página {{ page + 1 }}</span><button class="secondary" :disabled="(page+1)*20 >= total || busy" @click="changePage(page+1)">Próxima</button></div></section>
  <form v-else-if="view === 'form'" class="card form" @submit.prevent="save"><h2>Identificação</h2><p>Informe a loja e a origem vinculada ao pedido.</p><div class="grid"><label>ID da loja<input v-model="form.storeId" required :readonly="state.actor?.role === 'STORE'" placeholder="UUID da loja"></label><label>ID da origem<input v-model="form.originId" required placeholder="UUID da origem"></label></div><h2>Destinatário</h2><div class="grid"><label>Nome<input v-model="form.recipientName" required maxlength="150"></label><label>E-mail (opcional)<input v-model="form.recipientEmail" type="email" maxlength="254"></label></div><h2>Endereço de destino</h2><div class="grid"><label class="wide">Endereço<input v-model="form.destination.line1" required maxlength="200" placeholder="Rua e número"></label><label>Complemento<input v-model="form.destination.line2" maxlength="100"></label><label>CEP<input v-model="form.destination.postalCode" placeholder="00000-000" pattern="[0-9]{5}-?[0-9]{3}"></label><label>Cidade<input v-model="form.destination.city" required maxlength="100"></label><label>UF<input v-model="form.destination.state" required pattern="[A-Za-z]{2}" maxlength="2"></label><label>Latitude (opcional no rascunho)<input v-model="latitude" inputmode="decimal" pattern="-?([0-9]+([.][0-9]+)?|[.][0-9]+)"></label><label>Longitude (opcional no rascunho)<input v-model="longitude" inputmode="decimal" pattern="-?([0-9]+([.][0-9]+)?|[.][0-9]+)"></label></div><MapPicker @select="(lat, lon) => { latitude = String(lat); longitude = String(lon) }" /><h2>Itens</h2><p>Informe o peso unitário em quilogramas, com até três casas decimais.</p><div v-for="(item, index) in form.items" :key="index" class="item"><label>Descrição do item {{ index+1 }}<input v-model="item.description" required maxlength="200"></label><label>Quantidade<input v-model.number="item.quantity" type="number" min="1" max="10000" required></label><label>Peso unitário (kg)<input v-model="item.unitWeightKg" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,3})?" required placeholder="0.000"></label><button type="button" class="link" :disabled="form.items.length === 1" @click="form.items.splice(index,1)">Remover item {{ index+1 }}</button></div><button type="button" class="secondary" :disabled="form.items.length >= 100" @click="form.items.push({description:'',quantity:1,unitWeightKg:''})">＋ Adicionar item</button><div class="actions"><button class="primary" :disabled="busy">{{ editing ? 'Salvar alterações' : 'Criar pedido' }}</button></div></form>
  <section v-else-if="selected" class="detail"><div class="card"><div class="card-head"><div><span class="badge" :class="selected.status">{{ {DRAFT:'Rascunho',CONFIRMED:'Confirmado',CANCELLED:'Cancelado'}[selected.status] }}</span><h2>{{ selected.recipientName }}</h2><p class="mono">{{ selected.orderId }}</p></div><button v-if="selected.status === 'DRAFT'" class="secondary" :disabled="busy" @click="editOrder">Editar rascunho</button></div><dl><div><dt>Loja</dt><dd class="mono">{{ selected.storeId }}</dd></div><div><dt>Origem</dt><dd class="mono">{{ selected.originId }}</dd></div><div><dt>Destino</dt><dd>{{ selected.destination.line1 }}, {{ selected.destination.city }} / {{ selected.destination.state }}</dd></div><div><dt>E-mail</dt><dd>{{ selected.recipientEmail || 'Não informado' }}</dd></div><div><dt>Peso total</dt><dd>{{ selected.totalWeightKg }} kg</dd></div><div><dt>Frete</dt><dd>{{ selected.freightAmount === null ? 'Não cotado' : `R$ ${selected.freightAmount}` }}</dd></div><div><dt>Rastreamento</dt><dd>{{ selected.trackingCode || 'Não disponível' }}</dd></div></dl><h2>Itens</h2><ul><li v-for="(item, index) in selected.items" :key="index">{{ item.description }} · {{ item.quantity }} × {{ item.unitWeightKg }} kg</li></ul></div><div v-if="selected.status === 'CONFIRMED'" class="card"><h2>Pedido confirmado</h2><p>Os dados confirmados são imutáveis. O cancelamento após confirmação não está disponível.</p><p>Pagamento apenas simulado; não há cobrança real.</p><button class="secondary" :disabled="busy" @click="quoteOrder">Consultar cotação de frete</button><div v-if="quote && quote.orderId === selected.orderId"><h3>Snapshot da cotação</h3><dl><div><dt>ID</dt><dd>{{ quote.quoteId }}</dd></div><div><dt>Distância individual</dt><dd>{{ quote.distanceKm }} km</dd></div><div><dt>Tarifa por km</dt><dd>R$ {{ quote.tariffPerKm }}</dd></div><div><dt>Total</dt><dd>{{ quote.currency }} {{ quote.amount }}</dd></div><div><dt>Calculado em</dt><dd>{{ quote.calculatedAt }}</dd></div><div><dt>Fonte</dt><dd>{{ quote.source === 'FAKE' ? 'Distância simulada para desenvolvimento' : quote.source }}</dd></div></dl></div><p v-else-if="selected.freightAmount !== null">O valor registrado aparece no pedido. Consulte a cotação para ver o snapshot.</p></div><div v-if="selected.status === 'DRAFT'" class="card"><h2>Ações do pedido</h2><p v-if="selected.status === 'DRAFT'">Confira os dados e coordenadas antes de confirmar.</p><button v-if="selected.status === 'DRAFT'" class="primary" :disabled="busy" @click="confirmOrder">Confirmar pedido</button><form class="cancel" @submit.prevent="cancelOrder"><label>Motivo do cancelamento<input v-model="reason" required maxlength="500"></label><button class="danger" :disabled="busy">Cancelar pedido</button></form></div></section>
  </template></main></div>
</template>
